1	"use client";
2	
3	import { useState, type FormEvent } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import { createClient } from "@/lib/supabase/client";
7	import AuthShell from "@/components/auth-shell";
8	
9	export default function SignupPage() {
10	  const router = useRouter();
11	  const [email, setEmail] = useState("");
12	  const [password, setPassword] = useState("");
13	  const [confirmPassword, setConfirmPassword] = useState("");
14	  const [error, setError] = useState<string | null>(null);
15	  const [loading, setLoading] = useState(false);
16	  const [submitted, setSubmitted] = useState(false);
17	
18	  async function handleSubmit(e: FormEvent) {
19	    e.preventDefault();
20	    setError(null);
21	
22	    if (password !== confirmPassword) {
23	      setError("Password dan konfirmasi tidak sama.");
24	      return;
25	    }
26	    if (password.length < 6) {
27	      setError("Password minimal 6 karakter.");
28	      return;
29	    }
30	
31	    setLoading(true);
32	    const supabase = createClient();
33	    const { data, error } = await supabase.auth.signUp({ email, password });
34	    setLoading(false);
35	
36	    if (error) {
37	      setError(error.message);
38	      return;
39	    }
40	
41	    // If email confirmation is disabled (or already confirmed), signUp
42	    // returns an active session right away — no need to wait for email.
43	    if (data.session) {
44	      router.push("/onboarding");
45	      router.refresh();
46	      return;
47	    }
48	
49	    setSubmitted(true);
50	  }
51	
52	  if (submitted) {
53	    return (
54	      <AuthShell>
55	        <div className="text-center">
56	          <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-600 shadow-lg shadow-brand-600/20">
57	            <span className="text-lg font-bold text-white">K</span>
58	          </div>
59	          <h1 className="text-xl font-bold text-zinc-900">Cek email kamu</h1>
60	          <p className="mt-2 text-sm text-zinc-500">
61	            Kami sudah kirim link konfirmasi ke <strong>{email}</strong>. Klik link
62	            itu dulu sebelum bisa masuk.
63	          </p>
64	          <Link
65	            href="/login"
66	            className="mt-6 inline-block text-sm font-medium text-brand-600 hover:underline"
67	          >
68	            Kembali ke halaman masuk
69	          </Link>
70	        </div>
71	      </AuthShell>
72	    );
73	  }
74	
75	  return (
76	    <AuthShell>
77	      <div className="mb-8 text-center">
78	        <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-600 shadow-lg shadow-brand-600/20">
79	          <span className="text-lg font-bold text-white">K</span>
80	        </div>
81	        <h1 className="text-xl font-bold text-zinc-900">Daftar KasirKu</h1>
82	        <p className="mt-1 text-sm text-zinc-500">Buat akun pemilik toko baru</p>
83	      </div>
84	
85	      <form onSubmit={handleSubmit} className="space-y-4">
86	        <div>
87	          <label htmlFor="email" className="mb-1 block text-xs font-medium text-zinc-600">
88	            Email
89	          </label>
90	          <input
91	            id="email"
92	            type="email"
93	            autoComplete="email"
94	            required
95	            value={email}
96	            onChange={(e) => setEmail(e.target.value)}
97	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
98	            placeholder="kamu@toko.com"
99	          />
100	        </div>
101	        <div>
102	          <label htmlFor="password" className="mb-1 block text-xs font-medium text-zinc-600">
103	            Password
104	          </label>
105	          <input
106	            id="password"
107	            type="password"
108	            autoComplete="new-password"
109	            required
110	            value={password}
111	            onChange={(e) => setPassword(e.target.value)}
112	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
113	            placeholder="Minimal 6 karakter"
114	          />
115	        </div>
116	        <div>
117	          <label
118	            htmlFor="confirmPassword"
119	            className="mb-1 block text-xs font-medium text-zinc-600"
120	          >
121	            Ulangi Password
122	          </label>
123	          <input
124	            id="confirmPassword"
125	            type="password"
126	            autoComplete="new-password"
127	            required
128	            value={confirmPassword}
129	            onChange={(e) => setConfirmPassword(e.target.value)}
130	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm transition-shadow focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
131	            placeholder="••••••••"
132	          />
133	        </div>
134	
135	        {error && (
136	          <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>
137	        )}
138	
139	        <button
140	          type="submit"
141	          disabled={loading}
142	          className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white shadow-md shadow-brand-600/20 transition-all hover:bg-brand-700 hover:shadow-lg hover:shadow-brand-600/25 disabled:cursor-not-allowed disabled:opacity-60 disabled:shadow-none"
143	        >
144	          {loading ? "Memproses…" : "Daftar"}
145	        </button>
146	      </form>
147	
148	      <p className="mt-4 text-center text-xs text-zinc-400">
149	        Dengan mendaftar, kamu menyetujui{" "}
150	        <Link href="/terms" className="font-medium text-brand-600 hover:underline">
151	          Syarat &amp; Ketentuan
152	        </Link>{" "}
153	        dan{" "}
154	        <Link href="/privacy" className="font-medium text-brand-600 hover:underline">
155	          Kebijakan Privasi
156	        </Link>{" "}
157	        kami.
158	      </p>
159	
160	      <p className="mt-4 text-center text-sm text-zinc-500">
161	        Sudah punya akun?{" "}
162	        <Link href="/login" className="font-medium text-brand-600 hover:underline">
163	          Masuk
164	        </Link>
165	      </p>
166	    </AuthShell>
167	  );
168	}
